import { Fragment, PropsWithChildren, useEffect, useRef, MouseEvent, useMemo, useState } from "react";
import styles from "./modal.module.less";
import Portal from "@/core/helpers/portal";
import { ESCAPE_KEYS, modalStackManager } from "@/core/helpers/modal-stack-manager";
import { AnimatePresence, AnimationProps, motion } from "framer-motion";
import { multipleClassNames } from "@/core/helpers";

const FOCUSABLE_ELEMENTS_QUERY = "input, select, textarea, a, button, area";

export type VerticalContentPosition = "top" | "center" | "bottom";
export type HorizontalContentPosition = "left" | "center" | "right";

export type ModalProps = {
  id?: string | number;
  isOpen: boolean;
  className?: string;
  innerClassName?: string;
  /**
   * Function that will be called when the modal is being closed - modal doesn't know how to close itself
   */
  onClose: (e: any) => void;
  /**
   * Element that wraps entire web page except portal (if portal is used)
   * Used for creating focus trap and disable touch scroll
   */
  refWrapperElement?: HTMLElement | Element;
  /**
   * ClassName to apply on body and html for disabling scroll
   * @deprecated
   */
  disableScrollClassName?: string;
  /**
   * ID of element where to portal the modal (optional)
   */
  portalId?: string;

  /**
   * Aria-role of the modal, used for accessibility purposes
   *
   * Defaults to "dialog". Use "none" to unset role.
   */
  roleType?: "dialog" | "alertdialog" | "none";
  /**
   * Title used for accessibility purposes
   *
   * Is equivalent to `aria-labelledby` attribute, and should thus match the id of an element inside the modal.
   */
  modalTitle?: string;
  /**
   * Description used for accessibility purposes
   *
   * Is equivalent to `aria-describedby` attribute, and should thus match the id of an element inside the modal.
   */
  modalDescription?: string;

  modalOnAnimationEnd?: () => void;
  modalOnTransitionEnd?: () => void;
  overlayOnAnimationEnd?: () => void;
  overlayOnTransitionEnd?: () => void;
  /**
   * Set to true to disable the feature that focuses the first focusable element inside modal
   */
  disableInitialFocusInModal?: boolean;
  /**
   * @deprecated this now defaults to true and should be removed in a future release
   * Set to false to enable touch lock of refWrapperElement (used to prevent scrolling "behind" modal)
   */
  disableTouchLock?: boolean;
  /**
   * Set to false to disable closing modal on click on overlay
   */
  isClosable?: boolean;
  /**
   * How to position the content vertically. Default is "center".
   */
  verticalContentPosition?: VerticalContentPosition;
  /**
   * How to position the content horizontally. Default is "center".
   */
  horizontalContentPosition?: HorizontalContentPosition;
  /**
   * If set to true, will blur the background when modal is open.
   * @default false.
   */
  blurBackground?: boolean;
  /**
   * Will center the modal content vertically.
   * @deprecated use verticalContentPosition instead
   */
  centerContentVertically?: boolean;
  /**
   * Will center the modal content horizontally.
   * @deprecated use horizontalContentPosition instead
   */
  centerContentHorizontally?: boolean;
  modalContentAnimation?: AnimationProps;
};

export const Modal = ({
  id: inputId,
  isOpen: shouldOpen,
  className,
  innerClassName,
  onClose,
  refWrapperElement,
  disableScrollClassName = "",
  portalId,
  modalTitle,
  roleType = "dialog",
  modalDescription,
  modalOnAnimationEnd,
  modalOnTransitionEnd,
  overlayOnAnimationEnd,
  overlayOnTransitionEnd,
  disableInitialFocusInModal,
  disableTouchLock = true,
  isClosable = true,
  verticalContentPosition,
  horizontalContentPosition,
  blurBackground = false,
  centerContentVertically,
  centerContentHorizontally,
  children,
  modalContentAnimation,
}: PropsWithChildren<ModalProps>) => {
  const refOverlay = useRef<HTMLDivElement>(null);
  const [refModal, setRefModal] = useState<HTMLDivElement | null>(null);
  const isOpen = shouldOpen && refModal;

  const id = useMemo(() => inputId || Math.floor(Math.random() * 1000000 + 1), [inputId]);

  // Use vertical/horizontalContentPosition if set, otherwise use centerContentVertically/-Horizontally if set, otherwise default to center
  // Should be simplified when deprecated centerContentVertically/-Horizontally is removed
  verticalContentPosition =
    verticalContentPosition ||
    (centerContentVertically !== undefined ? (centerContentVertically ? "center" : "top") : "center");
  horizontalContentPosition =
    horizontalContentPosition ||
    (centerContentHorizontally !== undefined ? (centerContentHorizontally ? "center" : "left") : "center");

  useEffect(() => {
    if (isOpen) {
      // Only the first modal on the stack should lock; nested modals would
      // clobber the saved scrollY and lose the original scroll position.
      if (!modalStackManager.isAnyModalOpen()) {
        toggleScrollOnElement(true);
      }
      modalStackManager.registerNewlyOpenedModal({
        modalKey: id.toString(),
        documentEventListener: handleKeyDown,
      });
      handleOnOpen();
    } else {
      modalStackManager.unregisterClosedModal(id.toString());
      // Only the last modal to close should unlock.
      if (!modalStackManager.isAnyModalOpen()) {
        toggleScrollOnElement(false);
      }
    }

    return () => {
      // Unregister before checking, so isAnyModalOpen() reflects state without this modal.
      modalStackManager.unregisterClosedModal(id.toString());
      if (!modalStackManager.isAnyModalOpen()) {
        toggleScrollOnElement(false);
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, id]);

  /**
   * Focus trap for modal
   * When modal is open, focus should be trapped inside modal
   * When modal is closed, focus should be restored to the element that opened the modal
   * When modal is open and user presses Tab, focus should loop inside modal
   * When modal is open and user presses Shift + Tab, focus should loop inside modal in reverse
   */
  useEffect(() => {
    const modalRef = refModal;
    if (!modalRef) return undefined;

    const trapFocus = (event: KeyboardEvent) => {
      if (event.key === "Tab") {
        const focusableElements = modalRef.querySelectorAll(FOCUSABLE_ELEMENTS_QUERY);
        const firstFocusableElement = focusableElements?.[0] as HTMLElement;
        const lastFocusableElement = focusableElements?.[focusableElements.length - 1] as HTMLElement;

        if (event.shiftKey) {
          if (document.activeElement === firstFocusableElement) {
            lastFocusableElement?.focus();
            event.preventDefault();
          }
        } else {
          if (document.activeElement === lastFocusableElement) {
            firstFocusableElement?.focus();
            event.preventDefault();
          }
        }
      }
    };

    if (isOpen) {
      modalRef.addEventListener("keydown", trapFocus);
    } else {
      modalRef.removeEventListener("keydown", trapFocus);
    }

    return () => {
      modalRef.removeEventListener("keydown", trapFocus);
    };
  }, [isOpen, refModal]);

  const onModalOnAnimationEnd = () => {
    if (modalOnAnimationEnd && typeof modalOnAnimationEnd === "function") {
      modalOnAnimationEnd();
    }
  };

  const onModalOnTransitionEnd = () => {
    if (modalOnTransitionEnd && typeof modalOnTransitionEnd === "function") {
      modalOnTransitionEnd();
    }
  };

  const onOverlayOnAnimationEnd = () => {
    if (overlayOnAnimationEnd && typeof overlayOnAnimationEnd === "function") {
      overlayOnAnimationEnd();
    }
  };

  const onOverlayOnTransitionEnd = () => {
    if (overlayOnTransitionEnd && typeof overlayOnTransitionEnd === "function") {
      overlayOnTransitionEnd();
    }
  };

  const handleOnOpen = () => {
    if (!disableInitialFocusInModal) {
      focusInsideModal();
    }
  };

  const handleOverlayOnMouseDown = (event: MouseEvent) => {
    if (event.target === refOverlay.current && isClosable) {
      handleOnClose(event);
    }
  };

  const handleKeyDown = (event: KeyboardEvent) => {
    if (ESCAPE_KEYS.has(event?.key) && isClosable) {
      handleOnClose(event);
    }
  };

  const handleOnClose = (event: any) => {
    if (onClose) {
      onClose(event);
    }
  };

  const focusInsideModal = () => {
    const focusableElements = refModal?.querySelectorAll(FOCUSABLE_ELEMENTS_QUERY);
    if (focusableElements && focusableElements.length) {
      (focusableElements[0] as HTMLElement).focus();
    }
  };

  const toggleScrollOnElement = (showModal: boolean) => {
    if (showModal) {
      //Prevent scrolling behind the modal
      const scrollY = window.scrollY;
      document.body.style.position = "fixed";
      document.body.style.top = `-${scrollY}px`;
      document.body.style.width = "100%";

      if (refWrapperElement && !disableTouchLock) {
        refWrapperElement.addEventListener("touchmove", disableTouchMove, { passive: false });
      }
    } else {
      // Restore scrolling
      const scrollY = Math.abs(parseInt(document.body.style.top || "0"));
      document.body.style.position = "";
      document.body.style.top = "";
      document.body.style.width = "";
      window.scrollTo(0, scrollY);

      if (refWrapperElement && !disableTouchLock) {
        refWrapperElement.removeEventListener("touchmove", disableTouchMove);
      }
    }
  };

  const disableTouchMove = (event: any) => {
    event.preventDefault();
  };

  const renderModal = () => {
    return (
      <div className={[styles.modalWrapper, className].join(" ").trim()}>
        <div
          ref={refOverlay}
          onAnimationEnd={() => onOverlayOnAnimationEnd()}
          onTransitionEnd={() => onOverlayOnTransitionEnd()}
          onMouseDown={handleOverlayOnMouseDown}
          className={styles.modalOverlay}
          data-vertical-position={verticalContentPosition}
          data-horizontal-position={horizontalContentPosition}
          data-blur-background={!!blurBackground}
        >
          <motion.div
            {...modalContentAnimation}
            ref={setRefModal}
            onAnimationEnd={() => onModalOnAnimationEnd()}
            onTransitionEnd={() => onModalOnTransitionEnd()}
            role={roleType === "none" ? undefined : roleType}
            aria-modal="true"
            aria-labelledby={modalTitle}
            aria-describedby={modalDescription}
            className={multipleClassNames(styles.modalContent, innerClassName)}
            tabIndex={-1}
          >
            {children}
          </motion.div>
        </div>
      </div>
    );
  };

  return (
    <AnimatePresence>
      {shouldOpen && portalId && <Portal portalId={portalId}>{renderModal()}</Portal>}
      {shouldOpen && !portalId && <Fragment>{renderModal()}</Fragment>}
    </AnimatePresence>
  );
};
